{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://shokz.internal/alignment/record.schema.json",
  "title": "Alignment Concept Record",
  "description": "统一对齐记录契约。一条记录 = 一个需要全公司统一表达的概念。三个旧子工作（翻译对齐、PMKT 术语库、DM&KOL 术语库）都收敛到这一套 schema，靠 kind 区分性质、靠侧面（repr/explain/provenance）可空容纳不同填法。mkt copilot 接入时读本文件作为数据契约。",
  "type": "object",
  "required": ["id", "kind", "zh", "category", "repr"],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "description": "稳定主键（slug 或内容 hash）。不可用 zh 当键：产品表述里存在大量纯中文/同名多条会撞键。",
      "pattern": "^[a-z0-9][a-z0-9_-]*$"
    },
    "kind": {
      "type": "string",
      "description": "概念性质，决定列填法、分组与渲染到哪个 sheet。注意区别于来源文件：镭雕无论出自哪个文件都是业务术语，骨传导都是产品表述。",
      "enum": ["产品表述", "业务术语"]
    },
    "zh": {
      "type": "string",
      "description": "中文锚点。产品表述里是审定中文译法；业务术语里是中文全称。允许占位符 —。"
    },
    "category": {
      "type": "string",
      "description": "子分类。产品表述用 术语/卖点/动作/规格参数/颜色/包装配件/品类名/产品名/标语；业务术语用旧术语库的大类名。"
    },
    "subcategory": {
      "type": "string",
      "description": "可选二级分类。如产品表述动作下的「按键操作」，或业务术语 sheet 下的「1.3 Meta 受众定向类型」小标题。"
    },
    "repr": {
      "type": "object",
      "description": "对照轴：同一概念在不同表征下的标准值。key 走白名单，开放但可校验，防止 en 误拼成 eng 这类静默错误。",
      "additionalProperties": false,
      "properties": {
        "en": {
          "type": "string",
          "description": "英文。产品表述=审定英文译法；业务术语=英文全称。允许 —。"
        },
        "fr": {
          "type": "string",
          "description": "法文译法。产品表述常用；业务术语多为 —。允许 —。"
        },
        "abbr": {
          "type": "string",
          "description": "缩写/术语头词（业务术语用，如 KSP、FABE、品类词）。"
        },
        "en_full": {
          "type": "string",
          "description": "英文全称（当 abbr 是缩写、需要单列全称时使用）。"
        }
      }
    },
    "explain": {
      "type": "object",
      "description": "解释侧面。产品表述通常为空；业务术语填满。",
      "additionalProperties": false,
      "properties": {
        "def": {
          "type": "string",
          "description": "释义/说明。"
        },
        "usage": {
          "type": "string",
          "description": "常见使用场景。"
        }
      }
    },
    "provenance": {
      "type": "object",
      "description": "溯源侧面。产品表述强（须有源文件出处）；业务术语弱（多为内部约定）。",
      "additionalProperties": false,
      "properties": {
        "source": {
          "type": "string",
          "description": "出处。产品表述指向具体 MEET/SPEC/POP；业务术语可为空或注明内部来源。允许 —。"
        },
        "status": {
          "type": "string",
          "description": "确认状态。awaiting 收纳原始数据里「待 @某人 确认」一类未定项。",
          "enum": ["confirmed", "awaiting"],
          "default": "confirmed"
        }
      }
    }
  }
}

