chcp 65001 > $null; python -c @"
import json
from pathlib import Path
data=json.loads(Path('alignment/data/concepts.json').read_text(encoding='utf-8'))
try:
    import jsonschema
    schema=json.loads(Path('alignment/schema/record.schema.json').read_text(encoding='utf-8'))
    errs=0
    for r in data:
        try: jsonschema.validate(r,schema)
        except jsonschema.ValidationError as e:
            errs+=1
            if errs<=3: print('INVALID:', e.message, '->', r.get('id'))
    print(f'schema 校验: {len(data)-errs}/{len(data)} 通过', '(jsonschema)')
except ImportError:
    print('jsonschema 未安装，跳过形式校验')
print('--- 产品表述样本 ---')
for r in data[:2]: print(json.dumps(r,ensure_ascii=False))
print('--- 业务术语样本 ---')
biz=[r for r in data if r['kind']=='业务术语']
for r in biz[:2]: print(json.dumps(r,ensure_ascii=False))
print('--- awaiting 状态条数 ---')
print(sum(1 for r in data if r.get('provenance',{}).get('status')=='awaiting'))
"@

